<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#C678DD;">if</span><span style="--shiki-light:#D73A49;--shiki-dark:#ABB2BF;"> !</span><span style="--shiki-light:#005CC5;--shiki-dark:#56B6C2;"> which</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;"> flac</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;"> &amp;</span><span style="--shiki-light:#D73A49;--shiki-dark:#ABB2BF;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;"> /dev/null; </span><span style="--shiki-light:#D73A49;--shiki-dark:#C678DD;">then</span></span>
