<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">    path </span><span style="--shiki-light:#D73A49;--shiki-dark:#56B6C2;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#61AFEF;"> Path</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">(output_path).</span><span style="--shiki-light:#24292E;--shiki-dark:#61AFEF;">with_suffix</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;">&quot;.png&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">)</span></span>
